export const getGetReportStatsUrl = (params?: GetReportStatsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/reports/stats?${stringifiedParams}` : `/api/reports/stats`
}

/**
 * @summary Get detailed reporting statistics
 */
export const getReportStats = async (params?: GetReportStatsParams, options?: RequestInit): Promise<ReportStats> => {

  return customFetch<ReportStats>(getGetReportStatsUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





